ALTER TABLE users ADD COLUMN mfa_secret TEXT NULL,ADD COLUMN mfa_last_counter BIGINT NULL,ADD COLUMN auth_version INT UNSIGNED NOT NULL DEFAULT 1;
CREATE TABLE IF NOT EXISTS reschedule_transfers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,old_booking_id BIGINT UNSIGNED NOT NULL UNIQUE,new_booking_id BIGINT UNSIGNED NOT NULL UNIQUE,amount_cents BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(old_booking_id) REFERENCES bookings(id),FOREIGN KEY(new_booking_id) REFERENCES bookings(id));
